class KhatmTableData extends DataClass implements Insertable<KhatmTableData> {
  final String id;
  final String title;
  final DateTime startDate;
  final DateTime? endDate;
  final int targetDays;
  final String pagesRead;

  /// JSON map of 'YYYY-MM-DD' → pages read that day (for today's progress).
  ///
  /// Nullable on purpose: drift's `text()()` is NOT NULL and SQLite cannot
  /// add a NOT NULL column without a default to a table that already has
  /// rows — making this NOT NULL caused the schema-15→16 migration to throw
  /// "Cannot add a NOT NULL column with default value NULL" on every device
  /// with khatm data, which previously wiped the whole database.
  final String? dailyRead;
  final bool isCompleted;
  final String participantNames;
  final String participantAssignedJuzs;
  const KhatmTableData(
      {required this.id,
      required this.title,
      required this.startDate,
      this.endDate,
      required this.targetDays,
      required this.pagesRead,
      this.dailyRead,
      required this.isCompleted,
      required this.participantNames,
      required this.participantAssignedJuzs});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['title'] = Variable<String>(title);
    map['start_date'] = Variable<DateTime>(startDate);
    if (!nullToAbsent || endDate != null) {
      map['end_date'] = Variable<DateTime>(endDate);
    }
    map['target_days'] = Variable<int>(targetDays);
    map['pages_read'] = Variable<String>(pagesRead);
    if (!nullToAbsent || dailyRead != null) {
      map['daily_read'] = Variable<String>(dailyRead);
    }
    map['is_completed'] = Variable<bool>(isCompleted);
    map['participant_names'] = Variable<String>(participantNames);
    map['participant_assigned_juzs'] =
        Variable<String>(participantAssignedJuzs);
    return map;
  }

  KhatmTableCompanion toCompanion(bool nullToAbsent) {
    return KhatmTableCompanion(
      id: Value(id),
      title: Value(title),
      startDate: Value(startDate),
      endDate: endDate == null && nullToAbsent
          ? const Value.absent()
          : Value(endDate),
      targetDays: Value(targetDays),
      pagesRead: Value(pagesRead),
      dailyRead: dailyRead == null && nullToAbsent
          ? const Value.absent()
          : Value(dailyRead),
      isCompleted: Value(isCompleted),
      participantNames: Value(participantNames),
      participantAssignedJuzs: Value(participantAssignedJuzs),
    );
  }

  factory KhatmTableData.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return KhatmTableData(
      id: serializer.fromJson<String>(json['id']),
      title: serializer.fromJson<String>(json['title']),
      startDate: serializer.fromJson<DateTime>(json['startDate']),
      endDate: serializer.fromJson<DateTime?>(json['endDate']),
      targetDays: serializer.fromJson<int>(json['targetDays']),
      pagesRead: serializer.fromJson<String>(json['pagesRead']),
      dailyRead: serializer.fromJson<String?>(json['dailyRead']),
      isCompleted: serializer.fromJson<bool>(json['isCompleted']),
      participantNames: serializer.fromJson<String>(json['participantNames']),
      participantAssignedJuzs:
          serializer.fromJson<String>(json['participantAssignedJuzs']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'title': serializer.toJson<String>(title),
      'startDate': serializer.toJson<DateTime>(startDate),
      'endDate': serializer.toJson<DateTime?>(endDate),
      'targetDays': serializer.toJson<int>(targetDays),
      'pagesRead': serializer.toJson<String>(pagesRead),
      'dailyRead': serializer.toJson<String?>(dailyRead),
      'isCompleted': serializer.toJson<bool>(isCompleted),
      'participantNames': serializer.toJson<String>(participantNames),
      'participantAssignedJuzs':
          serializer.toJson<String>(participantAssignedJuzs),
    };
  }

  KhatmTableData copyWith(
          {String? id,
          String? title,
          DateTime? startDate,
          Value<DateTime?> endDate = const Value.absent(),
          int? targetDays,
          String? pagesRead,
          Value<String?> dailyRead = const Value.absent(),
          bool? isCompleted,
          String? participantNames,
          String? participantAssignedJuzs}) =>
      KhatmTableData(
        id: id ?? this.id,
        title: title ?? this.title,
        startDate: startDate ?? this.startDate,
        endDate: endDate.present ? endDate.value : this.endDate,
        targetDays: targetDays ?? this.targetDays,
        pagesRead: pagesRead ?? this.pagesRead,
        dailyRead: dailyRead.present ? dailyRead.value : this.dailyRead,
        isCompleted: isCompleted ?? this.isCompleted,
        participantNames: participantNames ?? this.participantNames,
        participantAssignedJuzs:
            participantAssignedJuzs ?? this.participantAssignedJuzs,
      );
  KhatmTableData copyWithCompanion(KhatmTableCompanion data) {
    return KhatmTableData(
      id: data.id.present ? data.id.value : this.id,
      title: data.title.present ? data.title.value : this.title,
      startDate: data.startDate.present ? data.startDate.value : this.startDate,
      endDate: data.endDate.present ? data.endDate.value : this.endDate,
      targetDays:
          data.targetDays.present ? data.targetDays.value : this.targetDays,
      pagesRead: data.pagesRead.present ? data.pagesRead.value : this.pagesRead,
      dailyRead: data.dailyRead.present ? data.dailyRead.value : this.dailyRead,
      isCompleted:
          data.isCompleted.present ? data.isCompleted.value : this.isCompleted,
      participantNames: data.participantNames.present
          ? data.participantNames.value
          : this.participantNames,
      participantAssignedJuzs: data.participantAssignedJuzs.present
          ? data.participantAssignedJuzs.value
          : this.participantAssignedJuzs,
    );
  }

  @override
  String toString() {
    return (StringBuffer('KhatmTableData(')
          ..write('id: $id, ')
          ..write('title: $title, ')
          ..write('startDate: $startDate, ')
          ..write('endDate: $endDate, ')
          ..write('targetDays: $targetDays, ')
          ..write('pagesRead: $pagesRead, ')
          ..write('dailyRead: $dailyRead, ')
          ..write('isCompleted: $isCompleted, ')
          ..write('participantNames: $participantNames, ')
          ..write('participantAssignedJuzs: $participantAssignedJuzs')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      title,
      startDate,
      endDate,
      targetDays,
      pagesRead,
      dailyRead,
      isCompleted,
      participantNames,
      participantAssignedJuzs);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is KhatmTableData &&
          other.id == this.id &&
          other.title == this.title &&
          other.startDate == this.startDate &&
          other.endDate == this.endDate &&
          other.targetDays == this.targetDays &&
          other.pagesRead == this.pagesRead &&
          other.dailyRead == this.dailyRead &&
          other.isCompleted == this.isCompleted &&
          other.participantNames == this.participantNames &&
          other.participantAssignedJuzs == this.participantAssignedJuzs);
}

