    this.mohdith = const Value.absent(),
    this.book = const Value.absent(),
    this.hadithNumber = const Value.absent(),
    this.degree = const Value.absent(),
    this.savedAt = const Value.absent(),
    this.rowid = const Value.absent(),
  })  : id = Value(id),
        hadithText = Value(hadithText);
  static Insertable<FavoriteDorarHadithTableData> custom({
    Expression<String>? id,
    Expression<String>? hadithText,
    Expression<String>? narrator,
    Expression<String>? mohdith,
    Expression<String>? book,
    Expression<String>? hadithNumber,
    Expression<String>? degree,
    Expression<DateTime>? savedAt,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (id != null) 'id': id,
      if (hadithText != null) 'hadith_text': hadithText,
      if (narrator != null) 'narrator': narrator,
      if (mohdith != null) 'mohdith': mohdith,
      if (book != null) 'book': book,
      if (hadithNumber != null) 'hadith_number': hadithNumber,
      if (degree != null) 'degree': degree,
      if (savedAt != null) 'saved_at': savedAt,
      if (rowid != null) 'rowid': rowid,
    });
  }

  FavoriteDorarHadithTableCompanion copyWith(
      {Value<String>? id,
      Value<String>? hadithText,
      Value<String?>? narrator,
      Value<String?>? mohdith,
      Value<String?>? book,
      Value<String?>? hadithNumber,
      Value<String?>? degree,
      Value<DateTime>? savedAt,
      Value<int>? rowid}) {
    return FavoriteDorarHadithTableCompanion(
      id: id ?? this.id,
      hadithText: hadithText ?? this.hadithText,
      narrator: narrator ?? this.narrator,
      mohdith: mohdith ?? this.mohdith,
      book: book ?? this.book,
      hadithNumber: hadithNumber ?? this.hadithNumber,
      degree: degree ?? this.degree,
      savedAt: savedAt ?? this.savedAt,
      rowid: rowid ?? this.rowid,
    );
  }

