  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<String>(id.value);
    }
    if (hadithText.present) {
      map['hadith_text'] = Variable<String>(hadithText.value);
    }
    if (narrator.present) {
      map['narrator'] = Variable<String>(narrator.value);
    }
    if (mohdith.present) {
      map['mohdith'] = Variable<String>(mohdith.value);
    }
    if (book.present) {
      map['book'] = Variable<String>(book.value);
    }
    if (hadithNumber.present) {
      map['hadith_number'] = Variable<String>(hadithNumber.value);
    }
    if (degree.present) {
      map['degree'] = Variable<String>(degree.value);
    }
    if (savedAt.present) {
      map['saved_at'] = Variable<DateTime>(savedAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

